(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)');document.querySelectorAll('.faq').forEach(group=>group.querySelectorAll('details').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)group.querySelectorAll('details').forEach(other=>{if(other!==item)other.open=false})})));document.querySelectorAll('video').forEach(video=>{video.addEventListener('play',()=>document.querySelectorAll('video').forEach(other=>{if(other!==video)other.pause()}));new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)video.pause()}),{threshold:0}).observe(video)});if(!reduce.matches&&matchMedia('(pointer:fine)').matches)document.querySelectorAll('.promise-grid article,.feature-card').forEach(card=>{card.addEventListener('pointermove',e=>{let r=card.getBoundingClientRect();card.style.setProperty('--rx',((.5-(e.clientY-r.top)/r.height)*4)+'deg');card.style.setProperty('--ry',(((e.clientX-r.left)/r.width-.5)*5)+'deg')});card.addEventListener('pointerleave',()=>{card.style.setProperty('--rx','0deg');card.style.setProperty('--ry','0deg')})});})();
